def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    if not man_patches: return image_patch
    man_patch = max(man_patches, key=lambda m: m.upper - m.lower)
    return man_patch.crop(man_patch.left, man_patch.lower, man_patch.right, man_patch.upper + 20)

def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    return image_patch.crop(0, 0, image.width // 2, image.height)
